#include <iostream>
#include <vector>
#include <queue>
#include <tuple>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, t;
    if (!(cin >> n >> t)) return 0;

    vector<int> tipo(n);
    for (int i = 0; i < n; ++i) {
        cin >> tipo[i];
    }

    vector<int> preco(n);
    for (int i = 0; i < n; ++i) {
        cin >> preco[i];
    }

    // Min-heap global: (preço, tipo, id)
    priority_queue<tuple<int, int, int>, 
                   vector<tuple<int, int, int>>, 
                   greater<tuple<int, int, int>>> global_pq;

    // Min-heaps por tipo: (preço, id)
    vector<priority_queue<pair<int, int>, 
                          vector<pair<int, int>>, 
                          greater<pair<int, int>>>> tipo_pq(t + 1);

    for (int i = 0; i < n; ++i) {
        global_pq.push({preco[i], tipo[i], i});
        tipo_pq[tipo[i]].push({preco[i], i});
    }

    int c;
    cin >> c;

    vector<bool> vendido(n, false);
    long long total_arrecadado = 0;

    for (int j = 0; j < c; ++j) {
        int u;
        cin >> u;

        if (u == 0) {
            // Cliente indeciso
            while (!global_pq.empty() && vendido[get<2>(global_pq.top())]) {
                global_pq.pop();
            }
            if (!global_pq.empty()) {
                auto [p, tp, id] = global_pq.top();
                global_pq.pop();
                vendido[id] = true;
                total_arrecadado += p;
            }
        } else {
            // Cliente decidido
            auto& pq = tipo_pq[u];
            while (!pq.empty() && vendido[pq.top().second]) {
                pq.pop();
            }
            if (!pq.empty()) {
                auto [p, id] = pq.top();
                pq.pop();
                vendido[id] = true;
                total_arrecadado += p;
            }
        }
    }

    cout << total_arrecadado << "\n";

    return 0;
}
